// NIRASI PASTRIES — SIMPLE, READABLE JAVASCRIPT

const products = [
  { id:1, name:'Classic Cinnamon Roll', category:'Pastries', price:3000, unit:'Single', tag:'Bestseller', description:'Soft, buttery swirls finished with a silky glaze.', image:'https://images.unsplash.com/photo-1509365465985-25d11c17e812?auto=format&fit=crop&w=700&q=85' },
  { id:2, name:'Oreo Cinnamon Roll', category:'Pastries', price:3800, unit:'Single', tag:'Fan favourite', description:'Our signature roll with a cookies-and-cream twist.', image:'https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=700&q=85' },
  { id:3, name:'Chocolate Cinnamon Roll', category:'Pastries', price:4000, unit:'Single', tag:'Chocolate lover', description:'A rich cocoa swirl for the days that need extra joy.', image:'data:image/jpeg;base64,' },
  { id:4, name:'Classic Banana Bread', category:'Breads', price:7000, unit:'Full loaf', tag:'Freshly baked', description:'Moist, comforting and lovely with your morning tea.', image:'https://images.unsplash.com/photo-1586444248902-2f64eddc13df?auto=format&fit=crop&w=700&q=85' },
  { id:5, name:'Oreo Banana Bread', category:'Breads', price:8500, unit:'Full loaf', tag:'A little extra', description:'Banana bread with crunchy chocolate cookie pieces.', image:'data:image/jpeg;base64,' },
  { id:6, name:'Mini Pancake Bites', category:'Bites', price:4500, unit:'15 pieces', tag:'Comes with dip', description:'Fluffy little bites with a dip for dunking.', image:'https://images.unsplash.com/photo-1528207776546-365bb710ee93?auto=format&fit=crop&w=700&q=85' },
  { id:7, name:'Cookie Bites', category:'Cookies', price:4600, unit:'10 pieces', tag:'Snack happy', description:'Golden, soft-centred cookie bites made for sharing.', image:'https://images.unsplash.com/photo-1499636136210-6f4ee915583e?auto=format&fit=crop&w=700&q=85' },
  { id:8, name:'Celebration Cake', category:'Cakes', price:25000, unit:'From', tag:'Made to order', description:'A centrepiece for birthdays, milestones and sweet surprises.', image:'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=700&q=85' },
  { id:9, name:'Butter Croissant', category:'Pastries', price:2500, unit:'Single', tag:'Morning favourite', description:'Flaky, golden layers with a delicate buttery centre.', image:'https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=700&q=85' },
  { id:10, name:'Chocolate Chip Cookies', category:'Cookies', price:3500, unit:'6 pieces', tag:'Crowd pleaser', description:'Crisp edges, soft middles and generous chocolate chips.', image:'data:image/jpeg;base64,' },
  { id:11, name:'Red Velvet Cupcakes', category:'Cakes', price:6000, unit:'Box of 4', tag:'Pretty & delicious', description:'Velvety cocoa sponge with a cloud of cream cheese frosting.', image:'https://images.unsplash.com/photo-1587668178277-295251f900ce?auto=format&fit=crop&w=700&q=85' },
  { id:12, name:'Brownie Squares', category:'Bites', price:5000, unit:'Box of 6', tag:'Fudgy goodness', description:'Deep chocolate flavour with soft, fudgy centres.', image:'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=700&q=85' }
];

// ---------- Helpers & state ----------
const $ = id => document.getElementById(id);
const all = selector => document.querySelectorAll(selector);
const money = value => new Intl.NumberFormat('en-NG', {
  style:'currency', currency:'NGN', maximumFractionDigits:0
}).format(value);

const grid = $('productGrid');
const search = $('productSearch');
let cart = [], filter = 'All', toastTimer;

// ---------- Products ----------
function filteredProducts() {
  const term = search.value.trim().toLowerCase();
  return products.filter(p => {
    const matchesFilter = filter === 'All' || p.category === filter;
    const text = `${p.name} ${p.category} ${p.description}`.toLowerCase();
    return matchesFilter && text.includes(term);
  });
}

function productCard(p, i) {
  const price = p.unit === 'From' ? `From ${money(p.price)}` : money(p.price);
  return `<article class="product-card" style="animation-delay:${Math.min(i * 55, 420)}ms">
    <div class="product-image">
      <img src="${p.image}" alt="${p.name}" loading="lazy">
      <span class="product-tag">${p.tag}</span>
      <button class="quick-add" data-add="${p.id}" aria-label="Add ${p.name} to cart">+</button>
    </div>
    <div class="product-info">
      <span class="product-category">${p.category} · ${p.unit}</span>
      <div class="product-name-row">
        <h3 class="product-name">${p.name}</h3><span class="product-price">${price}</span>
      </div>
      <p class="product-description">${p.description}</p>
    </div>
  </article>`;
}

function renderProducts() {
  const list = filteredProducts();
  grid.innerHTML = list.length
    ? list.map(productCard).join('')
    : `<div class="no-results"><h3>No treats found just yet.</h3><p>Try another search or browse everything.</p></div>`;
}

function setFilter(value) {
  filter = value;
  all('.filter-chip').forEach(btn => btn.classList.toggle('selected', btn.dataset.filter === value));
  renderProducts();
}

// ---------- Cart ----------
const cartCount = () => cart.reduce((sum, item) => sum + item.qty, 0);
const subtotal = () => cart.reduce((sum, item) => sum + item.price * item.qty, 0);

function addToCart(id) {
  const product = products.find(p => p.id === Number(id));
  if (!product) return;
  const item = cart.find(p => p.id === product.id);
  item ? item.qty++ : cart.push({ ...product, qty:1 });
  renderCart();
  showToast(`${product.name} added to your bag ♡`);
}

function changeQty(id, amount) {
  const item = cart.find(p => p.id === Number(id));
  if (!item) return;
  item.qty += amount;
  if (item.qty < 1) cart = cart.filter(p => p.id !== item.id);
  renderCart();
}

function removeItem(id) {
  cart = cart.filter(p => p.id !== Number(id));
  renderCart();
}

function cartItem(item) {
  return `<div class="cart-line">
    <img src="${item.image}" alt="${item.name}">
    <div><h4>${item.name}</h4><span class="line-price">${money(item.price)}</span>
      <div class="quantity-control"><button data-qty="${item.id}" data-delta="-1">−</button><span>${item.qty}</span><button data-qty="${item.id}" data-delta="1">+</button></div>
    </div>
    <div><strong class="line-price">${money(item.price * item.qty)}</strong><button class="remove-item" data-remove="${item.id}">Remove</button></div>
  </div>`;
}

function reviewItem(item) {
  return `<div class="review-line"><img src="${item.image}" alt=""><div><strong>${item.name}</strong><small>Qty: ${item.qty}</small></div><b>${money(item.price * item.qty)}</b></div>`;
}

function renderCart() {
  const count = cartCount(), empty = !cart.length;
  $('cartCount').textContent = count;
  $('drawerCount').textContent = `(${count})`;
  $('cartItems').innerHTML = cart.map(cartItem).join('');
  $('cartSubtotal').textContent = money(subtotal());
  $('cartEmpty').style.display = empty ? 'flex' : 'none';
  $('cartItems').style.display = empty ? 'none' : 'block';
  $('cartSummary').style.display = empty ? 'none' : 'block';
  $('checkoutItems').innerHTML = cart.map(reviewItem).join('');
  $('checkoutSubtotal').textContent = money(subtotal());
}

// ---------- Cart & checkout UI ----------
function openCart() {
  closeCheckout();
  $('cartDrawer').classList.add('open');
  $('overlay').classList.add('open');
  $('cartDrawer').setAttribute('aria-hidden', 'false');
  document.body.classList.add('no-scroll');
}

function closeCart() {
  $('cartDrawer').classList.remove('open');
  $('overlay').classList.remove('open');
  $('cartDrawer').setAttribute('aria-hidden', 'true');
  document.body.classList.remove('no-scroll');
}

function openCheckout() {
  if (!cart.length) return showToast('Your bag is empty — find a treat first.');
  closeCart();
  $('checkoutModal').classList.add('open');
  $('checkoutModal').setAttribute('aria-hidden', 'false');
  document.body.classList.add('no-scroll');
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  $('deliveryDate').min = tomorrow.toISOString().split('T')[0];
}

function closeCheckout() {
  $('checkoutModal').classList.remove('open');
  $('checkoutModal').setAttribute('aria-hidden', 'true');
  if (!$('cartDrawer').classList.contains('open')) document.body.classList.remove('no-scroll');
}

function showToast(message) {
  const toast = $('toast');
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 2500);
}

function submitOrder(event) {
  event.preventDefault();
  if (!cart.length) return;
  const data = new FormData(event.currentTarget);
  const ref = `NIR-${Math.random().toString(36).slice(2, 7).toUpperCase()}`;
  const items = cart.map(i => `${i.qty} × ${i.name} — ${money(i.price * i.qty)}`).join('<br>');
  $('successOrder').innerHTML = `<strong>Reference: ${ref}</strong><br>${items}<hr style="border:0;border-top:1px solid #e2d5c3"><strong>Subtotal: ${money(subtotal())}</strong><br>Payment: ${data.get('payment')}<br>Delivery: ${data.get('deliveryDate')}`;
  $('successMessage').textContent = `Thank you, ${data.get('fullName')}! Your order request is ready. Please note this demo does not send the order to Nirasi Pastries yet.`;
  $('checkoutForm').hidden = true;
  $('orderSuccess').hidden = false;
}

// ---------- Events ----------
grid.addEventListener('click', e => {
  const add = e.target.closest('[data-add]');
  if (add) addToCart(add.dataset.add);
});

$('filterList').addEventListener('click', e => {
  const btn = e.target.closest('[data-filter]');
  if (btn) setFilter(btn.dataset.filter);
});

search.addEventListener('input', renderProducts);
all('[data-category-link]').forEach(link => link.addEventListener('click', () => {
  search.value = '';
  setFilter(link.dataset.categoryLink);
}));

$('openCart').addEventListener('click', openCart);
$('closeCart').addEventListener('click', closeCart);
$('overlay').addEventListener('click', closeCart);
$('continueShopping').addEventListener('click', closeCart);
$('startShopping').addEventListener('click', () => {
  closeCart();
  $('shop').scrollIntoView({ behavior:'smooth' });
});

$('cartItems').addEventListener('click', e => {
  const qty = e.target.closest('[data-qty]');
  const remove = e.target.closest('[data-remove]');
  if (qty) changeQty(qty.dataset.qty, Number(qty.dataset.delta));
  if (remove) removeItem(remove.dataset.remove);
});

$('checkoutBtn').addEventListener('click', openCheckout);
$('closeCheckout').addEventListener('click', closeCheckout);
$('checkoutModal').addEventListener('click', e => {
  if (e.target === $('checkoutModal')) closeCheckout();
});
$('checkoutForm').addEventListener('submit', submitOrder);

$('finishOrder').addEventListener('click', () => {
  cart = [];
  renderCart();
  $('checkoutForm').reset();
  $('checkoutForm').hidden = false;
  $('orderSuccess').hidden = true;
  closeCheckout();
  $('shop').scrollIntoView({ behavior:'smooth' });
});

$('contactForm').addEventListener('submit', e => {
  e.preventDefault();
  $('contactFeedback').textContent = 'Thank you for reaching out! This demo form is ready to connect to your email or order system.';
  e.target.reset();
});

$('menuToggle').addEventListener('click', () => {
  const open = $('mainNav').classList.toggle('open');
  $('menuToggle').setAttribute('aria-expanded', open);
});

all('.main-nav a').forEach(link => link.addEventListener('click', () => {
  $('mainNav').classList.remove('open');
  $('menuToggle').setAttribute('aria-expanded', 'false');
}));

document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    closeCart();
    closeCheckout();
    $('mainNav').classList.remove('open');
  }
  if (e.key === '/' && !['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)) {
    e.preventDefault();
    search.focus();
    search.select();
  }
});

// ---------- Scroll reveal & premium motion ----------
const revealObserver = new IntersectionObserver(entries => entries.forEach(entry => {
  if (entry.isIntersecting) {
    entry.target.classList.add('visible');
    revealObserver.unobserve(entry.target);
  }
}), { threshold:.12 });
all('.reveal').forEach(el => revealObserver.observe(el));

(() => {
  const header = document.querySelector('.site-header');
  const count = $('cartCount');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const pointer = matchMedia('(hover:hover) and (pointer:fine)').matches;

  const updateHeader = () => header.classList.toggle('scrolled', scrollY > 35);
  updateHeader();
  addEventListener('scroll', updateHeader, { passive:true });

  const nav = [...document.querySelectorAll('.main-nav .nav-link')];
  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(entries => entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const link = nav.find(a => a.getAttribute('href') === `#${entry.target.id}`);
      if (link) {
        nav.forEach(a => a.classList.remove('active'));
        link.classList.add('active');
      }
    }), { rootMargin:'-38% 0px -52% 0px' });
    document.querySelectorAll('main section[id]').forEach(section => observer.observe(section));
  }

  if (pointer && !reduced) {
    document.addEventListener('pointermove', e => {
      const card = e.target.closest('.product-card');
      if (!card) return;
      const r = card.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - .5;
      const y = (e.clientY - r.top) / r.height - .5;
      card.style.transform = `perspective(900px) rotateX(${(-y * 2.2).toFixed(2)}deg) rotateY(${(x * 2.2).toFixed(2)}deg) translateY(-8px)`;
    });
    document.addEventListener('pointerout', e => {
      const card = e.target.closest('.product-card');
      if (card && !card.contains(e.relatedTarget)) card.style.transform = '';
    });
  }

  new MutationObserver(() => {
    grid.querySelectorAll('.product-card').forEach((card, i) => {
      card.style.animationDelay = `${Math.min(i * 70, 420)}ms`;
    });
  }).observe(grid, { childList:true });

  new MutationObserver(() => {
    count.classList.remove('bump');
    void count.offsetWidth;
    count.classList.add('bump');
  }).observe(count, { childList:true, characterData:true, subtree:true });

  all('.section-heading.reveal, .custom-copy.reveal').forEach(el => el.classList.add('reveal-left'));
  all('.feature-copy.reveal, .contact-form.reveal').forEach(el => el.classList.add('reveal-right'));
  all('.custom-collage.reveal').forEach(el => el.classList.add('reveal-scale'));
})();

// ---------- Start the page ----------
$('year').textContent = new Date().getFullYear();
renderProducts();
renderCart();
